std::atomic<float> g_iconLiftMm{1.0f};   // [gameplay] melee_skill_armed_icon_lift_mm: the skill icon in the mana medallion this many mm over its depth

wchar_t g_iniPath[MAX_PATH];
FILETIME g_iniTime{};

float IniF(const wchar_t* sec, const wchar_t* key, float def) {
    wchar_t buf[64], d[64];
    swprintf_s(d, L"%g", def);
    GetPrivateProfileStringW(sec, key, d, buf, 64, g_iniPath);
    wchar_t* end = nullptr;
    const float v = wcstof(buf, &end);
    return end != buf && std::isfinite(v) ? v : def;
}
bool IniB(const wchar_t* sec, const wchar_t* key, bool def) { return IniF(sec, key, def ? 1.0f : 0.0f) != 0.0f; }

// Sky: only in the open air. The area's biome comes from the game's
// BiomeSystem::SetCurrentBiome (hooked below); the exe names only the outdoor
// ones, dungeons and caves bring theirs from level data, so anything not on
// this list - [sky] outdoor in the ini replaces it - gets no sky. Tristram
// (act1_tristram, area 38), the monastery's courtyard (act1_court, the Outer Cloister -
// added 2026-10-07), Kurast (act3_kurast, 79-82), Travincal
// (act3_travincal_outdoors, 83), the River of Flame (act4_lava, 107), the Chaos
// Sanctuary (act4_diab, 108) and Nihlathak's Temple (expansion_wildtemple_tempenter,
// 121) come from level data too, and are open air.
SRWLOCK g_biomeLock = SRWLOCK_INIT;
std::vector<std::string> g_outdoor;
char g_biome[96] = "";                  // last name the game set, bare (no folder, no extension), lower case
std::atomic<uint32_t> g_biomeGen{0};    // bumped by every SetCurrentBiome

void LoadOutdoorBiomes() {
    wchar_t buf[1024];
    GetPrivateProfileStringW(L"sky", L"outdoor", L"act1_outdoors,act1_tristram,act1_court,act2_outdoors,act2_town,act3_jungle,act3_docktown,act3_kurast,act3_travincal_outdoors,act4_mesa,act4_lava,act4_diab,expansion_town,expansion_siege,expansion_mountaintop,expansion_ruins,expansion_ruins_snow,expansion_wildtemple_tempenter",
                             buf, (DWORD)std::size(buf), g_iniPath);
    std::vector<std::string> list;
    std::string cur;
    for (const wchar_t* p = buf;; ++p) {
        if (*p == L',' || *p == 0) {
            if (!cur.empty()) list.push_back(cur);
            cur.clear();
            if (!*p) break;
        } else if (*p != L' ' && *p != L'\t' && *p < 128) cur += (char)towlower(*p);
    }
    AcquireSRWLockExclusive(&g_biomeLock); g_outdoor = list; ReleaseSRWLockExclusive(&g_biomeLock);
    g_biomeGen.fetch_add(1);   // re-judged with the new list
}

// Cave ceiling (docs/plan_cave_ceiling.md): the biomes that get a vault over the
// void, [ceiling] biomes: act 1's caves, then its crypts (2026-10-07); the other kinds
// of dungeon one by one.
std::vector<std::string> g_ceilBiomes;   // under g_biomeLock
// Each kind of dungeon its own: [ceiling] height_<biome>, brightness_<biome>,
// light_radius_<biome>; a key not there takes the common one (height, brightness,
// light_radius). The user sets them per dungeon in the settings window.
// And relief_<biome>; its picture texture_<biome> (LoadCeilingTextures, below), one of
// the shader's 4 slots: a crypt's brick vault is not a cave's rock.
// And wet_, detail_, contrast_<biome>: the barracks' smooth slabs shone and stood
// grainy with the cave rock's (the user, 2026-10-07).
// And a cathedral's groin vault instead of rock: vault_<biome> 1, bay_ (its bays' width),
// rib_width_, rib_depth_, bay_x_ / bay_z_ (the bays moved onto the game's columns);
// relief_ is then how far the vault rises from its springing to the crown.
// And dome_<biome> 1: over what the game draws higher than the ceiling (an altar's canopy)
// it rises as a sphere dome_radius_ round, by dome_max_ at most (the shader's height map).
// dome_<biome> 1: over what the game draws higher than dome_find_ (or the ceiling) - the cathedral's
// altar canopy - one smooth dome dome_radius_ round, by dome_max_ at most; tex_size_<biome>: world
// units one picture spans (0 = 4 tiles); relief_pic_<biome>: 0 noise, 1 light / -1 dark / 2 coloured
// parts of the picture stand out. (The groin vault, the vault on the columns or the walls and the
// walls at the floor's edge were tried on 2026-10-07 and taken out - commit 4ac321d has them.)
struct CeilVaultCfg { bool dome = false; float domeRadius = 30.0f, domeMax = 30.0f, domeFind = 0.0f;
                      float texSize = 0.0f, reliefPic = 0.0f; };
struct CeilBiomeCfg { std::string biome; float height, bright, light, relief, wet, detail, contrast; CeilVaultCfg vault; int slot = 0; };
std::vector<CeilBiomeCfg> g_ceilBiomeCfg;   // under g_biomeLock

void LoadCeilingBiomes() {
    wchar_t buf[1024];
    GetPrivateProfileStringW(L"ceiling", L"biomes", L"act1_caves,act1_crypt,act1_barracks,act1_cathedral,act1_catacombs,act2_sewer,act2_palace_clean", buf, (DWORD)std::size(buf), g_iniPath);
    std::vector<std::string> list;
    std::string cur;
    for (const wchar_t* p = buf;; ++p) {
        if (*p == L',' || *p == 0) {
            if (!cur.empty()) list.push_back(cur);
            cur.clear();
            if (!*p) break;
        } else if (*p != L' ' && *p != L'\t' && *p < 128) cur += (char)towlower(*p);
    }
    std::vector<CeilBiomeCfg> cfg;
    for (const std::string& b : list) {
        const std::wstring w(b.begin(), b.end());
        cfg.push_back({b, std::clamp(IniF(L"ceiling", (L"height_" + w).c_str(), g_set.ceilHeight.load()), 1.0f, 500.0f),
                       std::clamp(IniF(L"ceiling", (L"brightness_" + w).c_str(), g_set.ceilBright.load()), 0.0f, 4.0f),
                       std::clamp(IniF(L"ceiling", (L"light_radius_" + w).c_str(), g_set.ceilLight.load()), 1.0f, 1000.0f),
                       std::clamp(IniF(L"ceiling", (L"relief_" + w).c_str(), g_set.ceilRelief.load()), 0.0f, 100.0f),
                       std::clamp(IniF(L"ceiling", (L"wet_" + w).c_str(), g_set.ceilWet.load()), 0.0f, 3.0f),
                       std::clamp(IniF(L"ceiling", (L"detail_" + w).c_str(), g_set.ceilDetail.load()), 0.0f, 10.0f),
                       std::clamp(IniF(L"ceiling", (L"contrast_" + w).c_str(), g_set.ceilContrast.load()), 0.0f, 5.0f)});
        CeilVaultCfg& v = cfg.back().vault;
        v.dome = IniB(L"ceiling", (L"dome_" + w).c_str(), false);
        v.domeRadius = std::clamp(IniF(L"ceiling", (L"dome_radius_" + w).c_str(), 30.0f), 5.0f, 200.0f);
        v.domeMax = std::clamp(IniF(L"ceiling", (L"dome_max_" + w).c_str(), 30.0f), 0.0f, 300.0f);
        v.domeFind = std::clamp(IniF(L"ceiling", (L"dome_find_" + w).c_str(), 0.0f), 0.0f, 500.0f);
        v.texSize = std::clamp(IniF(L"ceiling", (L"tex_size_" + w).c_str(), 0.0f), 0.0f, 1000.0f);
        v.reliefPic = std::clamp(IniF(L"ceiling", (L"relief_pic_" + w).c_str(), 0.0f), -1.0f, 2.0f);
    }
    AcquireSRWLockExclusive(&g_biomeLock);
    const bool same = g_ceilBiomes == list;
    g_ceilBiomes = list;
    for (CeilBiomeCfg& c : cfg)   // the picture's slot kept until LoadCeilingTextures looks again: no flicker on a reload
        for (const CeilBiomeCfg& old : g_ceilBiomeCfg) if (old.biome == c.biome) c.slot = old.slot;
    g_ceilBiomeCfg = cfg;
    ReleaseSRWLockExclusive(&g_biomeLock);
    if (!same) g_biomeGen.fetch_add(1);
}

// The ceiling's height, brightness, light reach, relief and picture slot (0 = none: the
// shader's own stone) in the area now - its biome's own, or the common ones.
void CeilingNow(float* height, float* bright, float* light, float* relief = nullptr, int* slot = nullptr) {
    float r = g_set.ceilRelief.load();
    int sl = 0;
    *height = g_set.ceilHeight.load(); *bright = g_set.ceilBright.load(); *light = g_set.ceilLight.load();
    AcquireSRWLockShared(&g_biomeLock);
    for (const CeilBiomeCfg& c : g_ceilBiomeCfg)
        if (c.biome == g_biome) { *height = c.height; *bright = c.bright; *light = c.light; r = c.relief; sl = c.slot; break; }
    ReleaseSRWLockShared(&g_biomeLock);
    if (relief) *relief = r;
    if (slot) *slot = sl;
}

// The stone's look in the area now: its shine, how far the picture's light parts stand out, its fine detail.
void CeilingLookNow(float* wet, float* detail, float* contrast, CeilVaultCfg* vault) {
    *wet = g_set.ceilWet.load(); *detail = g_set.ceilDetail.load(); *contrast = g_set.ceilContrast.load();
    *vault = CeilVaultCfg{};
    AcquireSRWLockShared(&g_biomeLock);
    for (const CeilBiomeCfg& c : g_ceilBiomeCfg)
        if (c.biome == g_biome) { *wet = c.wet; *detail = c.detail; *contrast = c.contrast; *vault = c.vault; break; }
    ReleaseSRWLockShared(&g_biomeLock);
}

bool IsCeilingBiome(const std::string& biome) {
    bool on = false;
    AcquireSRWLockShared(&g_biomeLock);
    for (const std::string& b : g_ceilBiomes) if (b == biome) { on = true; break; }
    ReleaseSRWLockShared(&g_biomeLock);
    return on;
}

// Starting palettes, by eye; picked by a part of the biome's name.
// act: the act slot 1..6 (6 = act 5 snow) whose brightness and pictures the area uses.
// bright: the ini key of the area's own brightness ([sky] brightness_*, on top of the common one).
struct SkyPalette { const char* part; float zenith[3], horizon[3], clouds, sun, sunElevDeg, sunAzDeg, stars; int act; };
const SkyPalette kPalettes[] = {
    {"snow",      {0.45f, 0.50f, 0.58f}, {0.80f, 0.82f, 0.85f}, 0.80f, 0.35f, 12, 140, 0.0f, 6},   // expansion_ruins_snow
    {"expansion", {0.20f, 0.25f, 0.32f}, {0.55f, 0.58f, 0.62f}, 0.60f, 0.30f, 10, 140, 0.0f, 5},   // cold ruins
    {"act5",      {0.20f, 0.25f, 0.32f}, {0.55f, 0.58f, 0.62f}, 0.60f, 0.30f, 10, 140, 0.0f, 5},
    {"act1",      {0.10f, 0.13f, 0.18f}, {0.35f, 0.30f, 0.28f}, 0.70f, 0.50f,  5, 230, 0.20f, 1},  // stormy night; painted by default (D2R_Sky_act1.png)
    {"act2",      {0.25f, 0.45f, 0.75f}, {0.85f, 0.75f, 0.55f}, 0.15f, 1.00f, 45,  60, 0.0f, 2},   // desert
    {"act3",      {0.15f, 0.30f, 0.35f}, {0.55f, 0.60f, 0.45f}, 0.50f, 0.40f, 35, 100, 0.0f, 3},   // humid haze
    {"act4",      {0.12f, 0.02f, 0.02f}, {0.60f, 0.15f, 0.05f}, 0.60f, 0.00f, 20,   0, 0.0f, 4},   // hell: smoke, no sun
};
constexpr int kDefaultPalette = 3;   // act1
// Per act, from [sky]: brightness_<act>, texture_<act> (the band round the
// viewer), cap_<act> (the zenith). An empty texture = the shader draws the sky
// from the palette. File names go to ReShade as preprocessor definitions.
const char* const kActKeys[7] = {"", "act1", "act2", "act3", "act4", "act5", "snow"};
const char* const kActDefs[7] = {"", "ACT1", "ACT2", "ACT3", "ACT4", "ACT5", "SNOW"};
struct SkyAct { float bright; std::string band, cap; bool bandOk, capOk; float fog[3]; bool fogSet;
                std::string nightBand, nightCap; bool nightOk; };   // [sky] night_<act> / night_cap_<act>: the night picture (gen_night_sky.py)
SRWLOCK g_skyCfgLock = SRWLOCK_INIT;
SkyAct g_skyAct[7];
// [fog] color_caves: one colour for every area off the outdoor list - caves,
// dungeons, crypts, towers. Empty = the act's own colour, as before.
struct CaveFog { float rgb[3]; bool set; };
CaveFog g_caveFog{};
std::atomic<uint32_t> g_skyCfgGen{0};   // bumped when a picture name changes

std::string Utf8(const wchar_t* w) {
    char b[1024];
    const int n = WideCharToMultiByte(CP_UTF8, 0, w, -1, b, sizeof b, nullptr, nullptr);
    return n > 0 ? std::string(b) : std::string();
}

// "#RRGGBB" (a leading # and spaces optional) to 0..1; false = empty or not a colour.
bool ParseHexColor(const wchar_t* text, float rgb[3]) {
    unsigned v = 0;
    while (*text == L' ' || *text == L'#') ++text;
    const bool ok = wcslen(text) >= 6 && swscanf_s(text, L"%6x", &v) == 1;
    for (int c = 0; c < 3; ++c) rgb[c] = ok ? ((v >> (16 - 8 * c)) & 0xFF) / 255.0f : 0.0f;
    return ok;
}

// [table] background: the void's fill in the table view; empty or unreadable = black.
SRWLOCK g_tableBgLock = SRWLOCK_INIT;
float g_tableBg[3] = {0.0f, 0.0f, 0.0f};

void LoadTableBackground() {
    wchar_t buf[64];
    GetPrivateProfileStringW(L"table", L"background", L"", buf, (DWORD)std::size(buf), g_iniPath);
    float rgb[3];
    if (!ParseHexColor(buf, rgb)) rgb[0] = rgb[1] = rgb[2] = 0.0f;
    AcquireSRWLockExclusive(&g_tableBgLock);
    for (int c = 0; c < 3; ++c) g_tableBg[c] = rgb[c];
    ReleaseSRWLockExclusive(&g_tableBgLock);
}

void LoadCaveFog() {
    wchar_t buf[64];
    GetPrivateProfileStringW(L"fog", L"color_caves", L"#100D0B", buf, (DWORD)std::size(buf), g_iniPath);
    CaveFog f{};
    f.set = ParseHexColor(buf, f.rgb);
    AcquireSRWLockExclusive(&g_skyCfgLock); g_caveFog = f; ReleaseSRWLockExclusive(&g_skyCfgLock);
}

// The folder ReShade lives in (shared/mod_layout.h): the mod's own reshade\ when this plugin runs as the D2RLoader mod D2R-VR
// (<game>\mods\D2R-VR\d2rloader\plugins) and that folder has ReShade64.dll; else the game's folder, as before. Its shaders,
// textures, ReShade.ini and add-ons are there. Taken once, with this plugin's own path.
const std::wstring& ReShadeDir() {
    static const std::wstring dir = [] {
        wchar_t self[MAX_PATH] = L"", game[MAX_PATH] = L"";
        HMODULE me = g_self;
        if (!me) GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT, (LPCWSTR)&ReShadeDir, &me);
        DWORD n = GetModuleFileNameW(me, self, MAX_PATH);
        while (n && self[n - 1] != L'\\') --n;
        self[n] = 0;
        n = GetModuleFileNameW(nullptr, game, MAX_PATH);
        while (n && game[n - 1] != L'\\') --n;
        game[n] = 0;
        const std::wstring mod = modlayout::ModRootOfPluginDir(self);
        const bool modReShade = !mod.empty() && GetFileAttributesW((mod + modlayout::kReShadeFolder + L"ReShade64.dll").c_str()) != INVALID_FILE_ATTRIBUTES;
        return modlayout::ReShadeDir(game, mod, modReShade);
    }();
    return dir;
}

// Where D2R VR's OWN ReShade files are (shared/mod_layout.h OurFilesDir): the mod's reshade\ whenever the plugin runs as the mod D2R-VR - D2R_DepthFog.fx, the
// sky / ceiling / Arcane pictures and FlatVR's add-on ship there, and ReShade finds them there both when it is the mod's own ReShade64.dll (that folder is its
// base, ReShadeDir) and when it is a dxgi.dll the player has beside the game (two search paths in its ReShade.ini, shared/reshade_paths.h; its base is the
// game's folder). Else the game's folder, as before the mod layout.
const std::wstring& OurFilesDir() {
    static const std::wstring dir = [] {
        wchar_t self[MAX_PATH] = L"", game[MAX_PATH] = L"";
        HMODULE me = g_self;
        if (!me) GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT, (LPCWSTR)&OurFilesDir, &me);
        DWORD n = GetModuleFileNameW(me, self, MAX_PATH);
        while (n && self[n - 1] != L'\\') --n;
        self[n] = 0;
        n = GetModuleFileNameW(nullptr, game, MAX_PATH);
        while (n && game[n - 1] != L'\\') --n;
        game[n] = 0;
        return modlayout::OurFilesDir(game, modlayout::ModRootOfPluginDir(self));
    }();
    return dir;
}

// A bare name is looked for where ReShade looks for D2R VR's pictures (reshade-shaders\Textures of D2R VR's own files, OurFilesDir).
bool SkyFileExists(const std::wstring& name) {
    if (name.find(L':') != std::wstring::npos || name.rfind(L"\\\\", 0) == 0) return GetFileAttributesW(name.c_str()) != INVALID_FILE_ATTRIBUTES;
    return GetFileAttributesW((OurFilesDir() + L"reshade-shaders\\Textures\\" + name).c_str()) != INVALID_FILE_ATTRIBUTES;
}

void LoadCrosshairFile();   // [input] crosshair (the flat crosshair's picture), with the cursor code

// The ceiling's pictures, one per kind of dungeon: [ceiling] texture_<biome>, by default
// D2R_Sky_ours/D2R_Ceiling_<biome>.png, else [ceiling] texture (the act 1 caves' stone).
// The different files go to the shader's 4 slots as D2R_CEILING_1..4 (like the skies);
// a biome whose file is missing gets slot 0: the shader draws the stone itself.
// 8: a fifth dungeon picture (the act 2 sewers' brick) found no slot and drew the shader's own stone (2026-10-07)
constexpr int kCeilSlots = 8;
std::string g_ceilSlot[kCeilSlots + 1];   // [1..8] the files, under g_skyCfgLock
bool g_ceilSlotOk[kCeilSlots + 1] = {};

std::wstring IniPath(const wchar_t* key, const wchar_t* def) {
    wchar_t buf[MAX_PATH];
    GetPrivateProfileStringW(L"ceiling", key, def, buf, MAX_PATH, g_iniPath);
    std::wstring f = buf;
    while (!f.empty() && (f.back() == L' ' || f.back() == L'"')) f.pop_back();
    while (!f.empty() && (f.front() == L' ' || f.front() == L'"')) f.erase(0, 1);
    return f;
}

void LoadCeilingTextures() {
    const std::wstring common = IniPath(L"texture", L"D2R_Sky_ours/D2R_Ceiling_act1_caves_walls.png");
    AcquireSRWLockExclusive(&g_biomeLock);
    std::vector<CeilBiomeCfg> cfg = g_ceilBiomeCfg;
    ReleaseSRWLockExclusive(&g_biomeLock);
    std::string slot[kCeilSlots + 1];
    int used = 0;
    for (CeilBiomeCfg& c : cfg) {
        const std::wstring w(c.biome.begin(), c.biome.end());
        std::wstring f = IniPath((L"texture_" + w).c_str(), (L"D2R_Sky_ours/D2R_Ceiling_" + w + L".png").c_str());
        if (f.empty() || !SkyFileExists(f)) f = common;
        c.slot = 0;
        if (f.empty() || !SkyFileExists(f)) { LogF("vrcam: cave ceiling %s - no picture found, the shader draws the stone itself", c.biome.c_str()); continue; }
        for (wchar_t& ch : f) if (ch == L'\\') ch = L'/';   // an FX string takes no backslashes
        const std::string name = Utf8(f.c_str());
        for (int k = 1; k <= used && !c.slot; ++k) if (slot[k] == name) c.slot = k;
        if (!c.slot && used < kCeilSlots) { slot[++used] = name; c.slot = used; }
    }
    AcquireSRWLockExclusive(&g_biomeLock);
    for (CeilBiomeCfg& now : g_ceilBiomeCfg)
        for (const CeilBiomeCfg& c : cfg) if (c.biome == now.biome) now.slot = c.slot;
    ReleaseSRWLockExclusive(&g_biomeLock);
    bool changed = false;
    AcquireSRWLockExclusive(&g_skyCfgLock);
    for (int k = 1; k <= kCeilSlots; ++k) {
        const bool ok = k <= used;
        if (g_ceilSlot[k] != slot[k] || g_ceilSlotOk[k] != ok) changed = true;
        g_ceilSlot[k] = slot[k]; g_ceilSlotOk[k] = ok;
    }
    ReleaseSRWLockExclusive(&g_skyCfgLock);
    if (changed) g_skyCfgGen.fetch_add(1);
}

void LoadSkyActs() {
    bool changed = false;
    for (int a = 1; a <= 6; ++a) {
        wchar_t key[32], buf[MAX_PATH];
        const std::wstring act(kActKeys[a], kActKeys[a] + strlen(kActKeys[a]));
        swprintf_s(key, L"brightness_%ls", act.c_str());
        const float bright = std::clamp(IniF(L"sky", key, 1.0f), 0.0f, 4.0f);
        std::string files[2]; bool ok[2];
        for (int k = 0; k < 2; ++k) {
            swprintf_s(key, k ? L"cap_%ls" : L"texture_%ls", act.c_str());
            wchar_t def[96];   // tools/gen_sky.py's names, in their own folder (the game's skies sit beside it)
            swprintf_s(def, k ? L"D2R_Sky_ours/D2R_SkyCap_%ls.png" : L"D2R_Sky_ours/D2R_Sky_%ls.png", act.c_str());
            GetPrivateProfileStringW(L"sky", key, def, buf, MAX_PATH, g_iniPath);
            std::wstring f = buf;
            while (!f.empty() && (f.back() == L' ' || f.back() == L'"')) f.pop_back();
            while (!f.empty() && (f.front() == L' ' || f.front() == L'"')) f.erase(0, 1);
            ok[k] = !f.empty() && SkyFileExists(f);
            if (!f.empty() && !ok[k]) LogF("vrcam: sky %s %s '%s' NOT FOUND - %s", kActKeys[a], k ? "cap" : "texture", Utf8(f.c_str()).c_str(),
                                          k ? "the zenith takes the palette colour" : "the shader draws this sky itself");
            for (wchar_t& c : f) if (c == L'\\') c = L'/';   // an FX string takes no backslashes
            files[k] = Utf8(f.c_str());
        }
        // The night pictures: both must be there (the cap blends with the band).
        std::string night[2]; bool nightOk = true;
        for (int k = 0; k < 2; ++k) {
            swprintf_s(key, k ? L"night_cap_%ls" : L"night_%ls", act.c_str());
            wchar_t def[96];
            swprintf_s(def, k ? L"D2R_Sky_ours/D2R_SkyCapNight_%ls.png" : L"D2R_Sky_ours/D2R_SkyNight_%ls.png", act.c_str());
            GetPrivateProfileStringW(L"sky", key, def, buf, MAX_PATH, g_iniPath);
            std::wstring f = buf;
            while (!f.empty() && (f.back() == L' ' || f.back() == L'"')) f.pop_back();
            while (!f.empty() && (f.front() == L' ' || f.front() == L'"')) f.erase(0, 1);
            nightOk = nightOk && !f.empty() && SkyFileExists(f);
            for (wchar_t& ch : f) if (ch == L'\\') ch = L'/';
            night[k] = Utf8(f.c_str());
        }
        // [fog] color_<act>: #RRGGBB; empty = the sky's horizon (or the dark default where there is no sky)
        swprintf_s(key, L"color_%ls", act.c_str());
        // defaults: each painted sky's horizon, a little darker (key missing; an empty key = from the sky)
        static const wchar_t* const kFogDef[7] = {L"", L"#242323", L"#683114", L"#50512F", L"#6C1809", L"#322A24", L"#7E8D99"};
        GetPrivateProfileStringW(L"fog", key, kFogDef[a], buf, MAX_PATH, g_iniPath);
        float fog[3] = {};
        const bool fogSet = ParseHexColor(buf, fog);
        AcquireSRWLockExclusive(&g_skyCfgLock);
        SkyAct& s = g_skyAct[a];
        if (s.band != files[0] || s.cap != files[1] || s.bandOk != ok[0] || s.capOk != ok[1] ||
            s.nightBand != night[0] || s.nightCap != night[1] || s.nightOk != nightOk) changed = true;
        s = {bright, files[0], files[1], ok[0], ok[1], {fog[0], fog[1], fog[2]}, fogSet, night[0], night[1], nightOk};
        ReleaseSRWLockExclusive(&g_skyCfgLock);
    }
    if (changed) g_skyCfgGen.fetch_add(1);
    LoadCaveFog();
}

// The act (1..6) a biome belongs to by its name, outdoors or not; 0 = cannot tell.
int ActOfBiome(const std::string& biome) {
    for (const SkyPalette& p : kPalettes) if (biome.find(p.part) != std::string::npos) return p.act;
    return 0;
}

// On the [sky] outdoor list: open air. Everything else in the world is a cave,
// a dungeon or a building.
bool IsOutdoorBiome(const std::string& biome) {
    bool outdoor = false;
    AcquireSRWLockShared(&g_biomeLock);
    for (const std::string& o : g_outdoor) if (o == biome) { outdoor = true; break; }
    ReleaseSRWLockShared(&g_biomeLock);
    return outdoor;
}

// -1 = no sky here. Called on the timer thread.
int SkyPaletteFor(const std::string& biome, bool always) {
    if (!always && !IsOutdoorBiome(biome)) return -1;
    for (int i = 0; i < (int)std::size(kPalettes); ++i) if (biome.find(kPalettes[i].part) != std::string::npos) return i;
    return kDefaultPalette;
}


// The game's own interface size ("Safe Screen Percent" in Saved Games\Diablo II
// Resurrected\Settings.json, 50..100), as a fraction: the toolbar's size and
// place follow it (hud.cpp). 1 when it cannot be read.
float GameInterfaceScale() {
    PWSTR dir = nullptr;
    std::wstring path;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_SavedGames, 0, nullptr, &dir))) path = std::wstring(dir) + L"\\Diablo II Resurrected\\Settings.json";
    if (dir) CoTaskMemFree(dir);
    FILE* f = path.empty() ? nullptr : _wfopen(path.c_str(), L"rb");
    if (!f) return 1.0f;
    std::string text(1 << 16, ' ');
    text.resize(fread(text.data(), 1, text.size(), f));
    fclose(f);
    return safescreen::Scale(text);   // (shared/safe_screen.h: the file's number over 100, 1 when it is missing or out of 30 - 100)
}

// Real stereo with the game's temporal anti-aliasing ("Anti Aliasing" 2 and up in Settings.json):
// it blends each picture with the one before - the other eye's - and every moving thing trails a
// ghost (the staff in the hand, 2026-10-09). At the plugin's start, before the game reads the
// file, it is set to FXAA (1); [stereo] keep_taa=1 leaves it alone.
void NoTemporalAA() {
    // (VR only: flat mode ([mode] platform=0) keeps the player's own anti-aliasing - the shipped ini has afr=1, for VR)
    if (g_set.platform.load() != 1 || !IniB(L"stereo", L"afr", false) || IniB(L"stereo", L"keep_taa", false)) return;
    PWSTR dir = nullptr;
    std::wstring path;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_SavedGames, 0, nullptr, &dir))) path = std::wstring(dir) + L"\\Diablo II Resurrected\\Settings.json";
    if (dir) CoTaskMemFree(dir);
    FILE* f = path.empty() ? nullptr : _wfopen(path.c_str(), L"rb");
    if (!f) return;
    std::string text(1 << 16, ' ');
    text.resize(fread(text.data(), 1, text.size(), f));
    fclose(f);
    const size_t at = text.find("\"Anti Aliasing\"");
    const size_t colon = at == std::string::npos ? at : text.find(':', at);
    if (colon == std::string::npos) return;
    size_t b = colon + 1;
    while (b < text.size() && (text[b] == ' ' || text[b] == '\t')) ++b;
    size_t e = b;
    while (e < text.size() && isdigit((unsigned char)text[e])) ++e;
    if (e == b) return;
    const int aa = atoi(text.c_str() + b);
    if (aa < 2) return;
    text.replace(b, e - b, "1");
    if (FILE* w = _wfopen(path.c_str(), L"wb")) {
        fwrite(text.data(), 1, text.size(), w);
        fclose(w);
        LogF("vrcam: the game's Anti Aliasing was %d (temporal: it mixes the eyes, a ghost behind everything moving) - set to FXAA ([stereo] keep_taa=1 to keep it)", aa);
    }
}

// The corner map for the hand (2026-10-12): the map in the headset - the orb or the flat panel - is the
// game's mini map taken out of the picture ([hud] map=1), and only the one on the right comes into the orb
// (the author, 2026-10-12): the game's map is on the right, the left or in the middle (Fullscreen) - in the
// middle players had the whole-screen map before their eyes, moving with the view, and no orb. At the
// plugin's start, before the game reads the file, in VR with the map out of the picture: "AutoMapMode" set
// to 2 - on the right (the game moves it left while a panel covers the right; seen in the log as the map's
// box on either side) - unless it is 2 already. The game's own options may change it; the next start sets
// it again. A read-only Settings.json (players were told to make it so for the window size) has the flag
// taken off first, as SafeGameWindow does; a file that cannot be written or has no AutoMapMode is logged.
void MiniMapForHand() {
    if (g_set.platform.load() != 1 || g_set.hudMap.load() != 1) return;
    PWSTR dir = nullptr;
    std::wstring path;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_SavedGames, 0, nullptr, &dir))) path = std::wstring(dir) + L"\\Diablo II Resurrected\\Settings.json";
    if (dir) CoTaskMemFree(dir);
    FILE* f = path.empty() ? nullptr : _wfopen(path.c_str(), L"rb");
    if (!f) return;
    std::string text(1 << 16, ' ');
    text.resize(fread(text.data(), 1, text.size(), f));
    fclose(f);
    const size_t at = text.find("\"AutoMapMode\"");
    const size_t colon = at == std::string::npos ? at : text.find(':', at);
    size_t b = colon == std::string::npos ? colon : colon + 1;
    while (b < text.size() && (text[b] == ' ' || text[b] == '\t')) ++b;
    size_t e = b;
    while (e < text.size() && isdigit((unsigned char)text[e])) ++e;
    if (b >= text.size() || e == b) {
        Log("vrcam: the game's Settings.json has no AutoMapMode - its map's side left as the game has it (only the map on the "
            "right comes into the hand: Options > Automap, the mini map on the right)");
        return;
    }
    const int mode = atoi(text.c_str() + b);
    if (mode == 2) return;
    text.replace(b, e - b, "2");
    const DWORD attr = GetFileAttributesW(path.c_str());
    const bool readOnly = attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_READONLY);
    if (readOnly) SetFileAttributesW(path.c_str(), attr & ~FILE_ATTRIBUTE_READONLY);
    if (FILE* w = _wfopen(path.c_str(), L"wb")) {
        fwrite(text.data(), 1, text.size(), w);
        fclose(w);
        LogF("vrcam: the game's AutoMapMode was %d (its map not on the right - only that one comes into the hand) - set to 2, "
             "the map on the right%s ([hud] map=0 leaves it alone)", mode, readOnly ? ", its read-only flag taken off" : "");
    } else {
        LogF("vrcam: the game's AutoMapMode is %d (its map not on the right - only that one comes into the hand) and Settings.json "
             "could not be written: put the mini map on the right in the game's options (Automap)", mode);
    }
}

// The game's windowed size, at the plugin's start - before the game reads Settings.json (shared/window_json.h, the policy and its
// tests). VR ([mode] platform=1, native OpenXR and FlatVR alike) has the square window (D2R VR Settings' "Square game window", written
// into Settings.json by the settings, kept by BigWindowTick). FLAT mode (the monitor) has none and uses the window and resolution the
// PLAYER set in the game: the mod chooses and writes no resolution there. A square left in Settings.json - by the settings for VR, or
// by the game itself at its quit (it saves the size its window had) - gives way in flat mode to the player's own window ([openxr]
// window_before, window_mode_before: kept before the square was first written, size and mode); with none kept nothing is written and
// the log says so. The player's own window is kept in every mode while it is the file's. Flat players of 0.166 started in the square:
// the shipped ini has square_window=1.
void ReconcileGameWindow() {
    PWSTR dir = nullptr;
    std::wstring path;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_SavedGames, 0, nullptr, &dir))) path = std::wstring(dir) + L"\\Diablo II Resurrected\\Settings.json";
    if (dir) CoTaskMemFree(dir);
    FILE* f = path.empty() ? nullptr : _wfopen(path.c_str(), L"rb");
    if (!f) return;
    std::string text(1 << 16, ' ');
    text.resize(fread(text.data(), 1, text.size(), f));
    fclose(f);
    const winjson::Windowed now = winjson::Read(text);
    if (!now.ok) return;
    winjson::Own own;
    {
        wchar_t b[32] = L"";
        GetPrivateProfileStringW(L"openxr", L"window_before", L"", b, 32, g_iniPath);
        swscanf_s(b, L"%dx%d", &own.w, &own.h);
        own.mode = (int)GetPrivateProfileIntW(L"openxr", L"window_mode_before", -1, g_iniPath);
    }
    const bool vr = g_set.platform.load() == 1;
    const winjson::Plan plan = winjson::ForPlatform(vr, IniB(L"openxr", L"square_window", false), now, own);
    if (plan.saveOwn && (plan.own.w != own.w || plan.own.h != own.h || plan.own.mode != own.mode)) {
        wchar_t b[32];
        swprintf_s(b, L"%dx%d", plan.own.w, plan.own.h);
        WritePrivateProfileStringW(L"openxr", L"window_before", b, g_iniPath);
        swprintf_s(b, L"%d", plan.own.mode);
        WritePrivateProfileStringW(L"openxr", L"window_mode_before", b, g_iniPath);
        LogF("vrcam: the player's own window %dx%d (mode %d) kept in d2r_vr.ini ([openxr] window_before) before a square window", plan.own.w, plan.own.h, plan.own.mode);
    }
    if (plan.unknownOwn)
        LogF("vrcam: flat mode ([mode] platform=0): the game's windowed size is %dx%d (VR's square) and no window of yours was kept: the game uses it - set the "
             "window you want in the game's Options > Video (the mod chooses no resolution in flat mode)", now.w, now.h);
    if (!plan.write) return;
    bool ok = false;
    const std::string out = winjson::With(text, plan.w, plan.h, plan.mode, &ok);
    if (!ok || out == text) return;
    const DWORD attr = GetFileAttributesW(path.c_str());
    if (attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_READONLY)) SetFileAttributesW(path.c_str(), attr & ~FILE_ATTRIBUTE_READONLY);
    if (FILE* o = _wfopen(path.c_str(), L"wb")) {
        fwrite(out.data(), 1, out.size(), o);
        fclose(o);
        LogF("vrcam: flat mode ([mode] platform=0): the game's windowed size was %dx%d (VR's square) - %s: set to %dx%d%s", now.w, now.h, plan.why, plan.w, plan.h,
             plan.mode >= 0 ? ", its window mode too" : "");
    } else {
        LogF("vrcam: flat mode: the game's windowed size is %dx%d (VR's square) and Settings.json could not be written: set a window in the game's Options > Video", now.w, now.h);
    }
}

// The game's frame cap ("Framerate Cap" in Settings.json), at the plugin's start - before the game reads the file (shared/frame_cap.h,
// the policy and its tests). The headset's rate writes a cap in VR (D2R VR Settings: a game frame per headset frame) and that cap must
// not stay in force in flat mode (the monitor): FLAT uses the player's own - the cap VR wrote goes, the one kept before it ([stereo]
// cap_before) comes back; none kept: nothing is written, the log says so. In VR only the player's own is kept: a cap in the file that
// is not the one VR wrote last ([stereo] cap_written) is his.
void ReconcileFrameCap() {
    PWSTR dir = nullptr;
    std::wstring path;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_SavedGames, 0, nullptr, &dir))) path = std::wstring(dir) + L"\\Diablo II Resurrected\\Settings.json";
    if (dir) CoTaskMemFree(dir);
    FILE* f = path.empty() ? nullptr : _wfopen(path.c_str(), L"rb");
    if (!f) return;
    std::string text(1 << 16, ' ');
    text.resize(fread(text.data(), 1, text.size(), f));
    fclose(f);
    const int now = framecap::Read(text);
    if (now < 0) return;
    framecap::State s;
    s.own = (int)GetPrivateProfileIntW(L"stereo", L"cap_before", -1, g_iniPath);
    s.written = (int)GetPrivateProfileIntW(L"stereo", L"cap_written", -1, g_iniPath);
    const bool vr = g_set.platform.load() == 1;
    framecap::Plan plan;
    if (vr) {
        if (now != s.written && now != s.own) { plan.saveOwn = true; plan.own = now; }
        // what the settings write for this headset rate and 3D mode, and why (one rule: shared/frame_cap.h VrCapFor)
        const int hz = framecap::HzOfRate((int)IniF(L"stereo", L"headset_rate", 3.0f));
        const framecap::VrCap c = framecap::VrCapFor(hz, IniB(L"stereo", L"afr", false), IniB(L"stereo", L"pair_per_tick", false), xr::On(),
                                                     IniF(L"flatvr", L"frame_sync", 0.0f) != 0.0f);
        LogF("vrcam: frame cap - the game's file has %d; for the headset's %d Hz in this 3D mode D2R VR Authentic Settings writes %d%s (%s)", now, hz, c.value,
             c.factor ? "" : " (none)", framecap::Reason(c.why));
    } else {
        plan = framecap::ForFlat(now, s);
    }
    if (plan.saveOwn) {
        wchar_t b[16];
        swprintf_s(b, L"%d", plan.own);
        WritePrivateProfileStringW(L"stereo", L"cap_before", b, g_iniPath);
        LogF("vrcam: the player's own frame cap %d kept in d2r_vr.ini ([stereo] cap_before) before VR's", plan.own);
    }
    if (plan.unknownOwn)
        LogF("vrcam: flat mode ([mode] platform=0): the game's frame cap is %d (VR's rate) and none of yours was kept: the game uses it - set the cap you want in the "
             "game's Options > Video (the mod chooses no frame cap in flat mode)", now);
    if (!plan.write) return;
    bool ok = false;
    const std::string out = framecap::With(text, plan.value, &ok);
    if (!ok || out == text) return;
    const DWORD attr = GetFileAttributesW(path.c_str());
    if (attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_READONLY)) SetFileAttributesW(path.c_str(), attr & ~FILE_ATTRIBUTE_READONLY);
    if (FILE* o = _wfopen(path.c_str(), L"wb")) {
        fwrite(out.data(), 1, out.size(), o);
        fclose(o);
        LogF("vrcam: flat mode ([mode] platform=0): the game's frame cap was %d (VR's rate) - %s: set to %d", now, plan.why, plan.value);
    } else {
        LogF("vrcam: flat mode: the game's frame cap is %d (VR's rate) and Settings.json could not be written: set the cap you want in the game's Options > Video", now);
    }
}

// The game's interface size ("Safe Screen Percent" in Settings.json), at the plugin's start - before the game reads the file (shared/safe_screen.h,
// the policy and its tests). At the game's default, 100, the interface is cut off at the edges in the headset (a player lowered it to 70 by hand):
// VR starts it at 80 where the player has chosen none (any value but 100 is his choice and stays) - [hud] safe_screen_vr, on - and keeps the
// 100 he had ([hud] safe_screen_before) and what VR wrote ([hud] safe_screen_written). FLAT mode (and the box unticked) has the player's own: VR's
// 80 goes, the kept value comes back; none kept: nothing is written, the log says so. Returns true when it wrote the file (the interface scale
// the toolbar's cut and the hand's globes are worked out from is read again by the caller).
bool ReconcileSafeScreen() {
    PWSTR dir = nullptr;
    std::wstring path;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_SavedGames, 0, nullptr, &dir))) path = std::wstring(dir) + L"\\Diablo II Resurrected\\Settings.json";
    if (dir) CoTaskMemFree(dir);
    FILE* f = path.empty() ? nullptr : _wfopen(path.c_str(), L"rb");
    const bool vr = g_set.platform.load() == 1, box = IniB(L"hud", L"safe_screen_vr", true);
    if (!f) {
        if (vr && box) Log("vrcam: the game's Settings.json is not there yet (the game writes it when it quits the first time): its interface size is the game's 100 for this run, "
                           "VR starts it at 80 from the next one ([hud] safe_screen_vr)");
        return false;
    }
    std::string text(1 << 16, ' ');
    text.resize(fread(text.data(), 1, text.size(), f));
    fclose(f);
    const int now = safescreen::Read(text);
    if (now < 0) {
        if (vr && box) Log("vrcam: the game's Settings.json has no Safe Screen Percent: its interface size is left as the game has it (VR starts it at 80 once the key is there)");
        return false;
    }
    safescreen::State s;
    s.own = (int)GetPrivateProfileIntW(L"hud", L"safe_screen_before", -1, g_iniPath);
    s.written = (int)GetPrivateProfileIntW(L"hud", L"safe_screen_written", -1, g_iniPath);
    // VR: the picture's shape decides what VR starts at and whether two side panels (a trader or the mercenary on the left, the inventory on the right)
    // fit it: in a square picture they do up to 80 % (shared/safe_screen.h, the numbers of the game's own layout) - above it the outer columns are off the
    // picture's edges or under the other panel, and cannot be seen or pointed at; the headset's own, taller shape (2496 x 2688) needs 74.
    float aspect = 1.0f;
    if (vr) {
        wchar_t hp[MAX_PATH];
        wcscpy_s(hp, g_iniPath);
        if (wchar_t* slash = wcsrchr(hp, L'\\')) slash[1] = 0;
        wcscat_s(hp, L"d2r_vr_headset.ini");   // what the headset's runtime recommended at the last native session
        const rendersize::Pick pick = rendersize::FromIni((int)IniF(L"render", L"vr_resolution", 0.0f), (int)IniF(L"render", L"vr_resolution_px", 0.0f));
        const bool native = IniB(L"openxr", L"on", false);   // (FlatVR has no render size: its picture is the window)
        const winjson::Windowed win = winjson::Read(text);
        aspect = safescreen::PictureAspect(native && pick.kind == rendersize::Kind::Square, native && pick.kind == rendersize::Kind::Headset,
                                           (int)GetPrivateProfileIntW(L"headset", L"recommended_w", 0, hp), (int)GetPrivateProfileIntW(L"headset", L"recommended_h", 0, hp),
                                           IniB(L"openxr", L"square_window", false), win.ok ? win.w : 0, win.ok ? win.h : 0);
    }
    const safescreen::Plan plan = vr && box ? safescreen::ForVr(now, s, true, safescreen::VrValueFor(aspect)) : safescreen::ForFlat(now, s, false);
    auto fitLine = [&](int pct) {
        if (!vr) return;
        const int fit = safescreen::FitPercent(aspect);
        if (safescreen::PanelsFit(pct, aspect))
            LogF("vrcam: interface size %d%%: two open side panels (a trader or the mercenary and the inventory) fit the picture (its width %.2f of its height, up to %d%%)", pct, aspect, fit);
        else
            LogF("vrcam: interface size %d%% is too big for the picture (its width %.2f of its height): two open side panels (a trader or the mercenary and the inventory) overlap "
                 "or run off its edges, their outer columns cannot be reached - %d%% or less", pct, aspect, fit);
    };
    wchar_t b[16];
    if (plan.saveOwn) {
        swprintf_s(b, L"%d", plan.own);
        WritePrivateProfileStringW(L"hud", L"safe_screen_before", b, g_iniPath);
    }
    if (plan.saveWritten) {
        swprintf_s(b, L"%d", plan.written);
        WritePrivateProfileStringW(L"hud", L"safe_screen_written", b, g_iniPath);
    }
    if (plan.clearWritten) WritePrivateProfileStringW(L"hud", L"safe_screen_written", L"-1", g_iniPath);
    if (plan.unknownOwn)
        LogF("vrcam: the game's interface size is %d (VR's) and none of yours was kept: the game uses it - set the size you want in the game's Options > Video "
             "([hud] safe_screen_vr off keeps the game's own)", now);
    if (!plan.write) {
        if (vr && box && now != safescreen::kGameDefault)
            LogF("vrcam: the game's interface size is %d%% - %s: left as it is", now, now == s.written ? "VR's" : "yours (not the game's default 100)");
        fitLine(now);
        return false;
    }
    bool ok = false;
    const std::string out = safescreen::With(text, plan.value, &ok);
    if (!ok || out == text) return false;
    const DWORD attr = GetFileAttributesW(path.c_str());
    if (attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_READONLY)) SetFileAttributesW(path.c_str(), attr & ~FILE_ATTRIBUTE_READONLY);
    if (FILE* o = _wfopen(path.c_str(), L"wb")) {
        fwrite(out.data(), 1, out.size(), o);
        fclose(o);
        if (vr && box)
            LogF("vrcam: the game's interface size was the game's default %d%% - %s: set to %d%% for VR (your %d%% is kept in d2r_vr.ini and comes back in flat mode; "
                 "[hud] safe_screen_vr=0 leaves it alone)", now, plan.why, plan.value, now);
        else
            LogF("vrcam: flat mode: the game's interface size was %d%% (VR's) - %s: set to %d%%", now, plan.why, plan.value);
        fitLine(plan.value);
        return true;
    }
    LogF("vrcam: the game's interface size is %d%% and Settings.json could not be written: set it in the game's Options > Video", now);
    return false;
}

// D2R itself dies at its title screen with a window taller than about 2400 ("A Fixed sized vector
// tried to reallocate" in its blz-log.txt, then its own crash handler; 2600 and 3000 tried, 2026-10-11).
// Players were told on Discord to put 3000x3000 into Settings.json and make it read-only: every start
// died, and vrcam's start guard then switched native OpenXR off - flat on the monitor. At the plugin's
// start, before the game reads the file: a windowed size taller than 2400 is cut to 2400 (a square
// stays square), the read-only flag taken off first (it kept the bad size for good).
void SafeGameWindow() {
    if (g_set.platform.load() != 1) return;   // flat mode: the game's own window and resolution, nothing of ours written (the cut is VR's, for its squares)
    PWSTR dir = nullptr;
    std::wstring path;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_SavedGames, 0, nullptr, &dir))) path = std::wstring(dir) + L"\\Diablo II Resurrected\\Settings.json";
    if (dir) CoTaskMemFree(dir);
    FILE* f = path.empty() ? nullptr : _wfopen(path.c_str(), L"rb");
    if (!f) return;
    std::string text(1 << 16, ' ');
    text.resize(fread(text.data(), 1, text.size(), f));
    fclose(f);
    const char* key = "\"Screen Resolution (Windowed)\"";
    const size_t at = text.find(key);
    const size_t q1 = at == std::string::npos ? at : text.find('"', text.find(':', at));
    const size_t q2 = q1 == std::string::npos ? q1 : text.find('"', q1 + 1);
    if (q2 == std::string::npos) return;
    int w = 0, h = 0;
    if (sscanf_s(text.c_str() + q1 + 1, "%dx%d", &w, &h) != 2) return;
    // the game builds its title screen at the size it starts with, and dies there when it is very tall
    // (3000 even on a 4000x4000 monitor; 2400 lives): it starts as tall as the main monitor holds, 2400 at most - D2R VR Settings' square
    // window grows it to its size after the title screen (BigWindowTick), on a monitor that holds it
    // and no taller than the main monitor holds (its work area less a frame): the menus need no more
    int limit = 2400;
    {
        MONITORINFO mi{sizeof mi};
        if (GetMonitorInfoW(MonitorFromPoint(POINT{0, 0}, MONITOR_DEFAULTTOPRIMARY), &mi))
            limit = std::max(480, std::min(limit, (int)(mi.rcWork.bottom - mi.rcWork.top) - 45));
    }
    if (h <= limit) return;
    const int nh = limit, nw = w == h ? limit : w;
    const std::string size = std::to_string(nw) + "x" + std::to_string(nh);
    text.replace(q1 + 1, q2 - q1 - 1, size);
    const DWORD attr = GetFileAttributesW(path.c_str());
    if (attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_READONLY)) SetFileAttributesW(path.c_str(), attr & ~FILE_ATTRIBUTE_READONLY);
    if (FILE* o = _wfopen(path.c_str(), L"wb")) {
        fwrite(text.data(), 1, text.size(), o);
        fclose(o);
        LogF("vrcam: the game's windowed size was %dx%d - taller than the main monitor holds (%d; D2R builds its title screen at "
             "that size and closes past ~2400): set to %s%s (D2R VR Authentic Settings' square window grows it in a game)", w, h, limit, size.c_str(),
             attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_READONLY) ? ", its read-only flag taken off" : "");
    } else {
        LogF("vrcam: the game's windowed size is %dx%d - taller than ~2400 D2R itself closes at its title screen, and Settings.json "
             "could not be written: set it to 2400x2400 or less by hand", w, h);
    }
}

