        const bool fix = IniB(L"render", L"light_bounds_fix", true), flat = g_set.platform.load() == 0;
        lightbounds::Configure(fix, !flat || IniB(L"render", L"light_bounds_flat", true), IniB(L"debug", L"log_compute_shaders", false), flat);
